import { mkdirSync, writeFileSync } from "node:fs";
import WebSocket from "ws";
const out = "screenshots/mat03";
mkdirSync(out, { recursive: true });
const targets = await (await fetch("http://127.0.0.1:9223/json/list")).json();
const ws = new WebSocket(targets.find(t => t.type === "page").webSocketDebuggerUrl);
await new Promise(r => ws.once("open", r));
let seq = 0;
const pending = new Map();
ws.on("message", raw => {
  const m = JSON.parse(raw); const p = pending.get(m.id);
  if (p) { pending.delete(m.id); m.error ? p.reject(Error(m.error.message)) : p.resolve(m.result); }
});
const cdp = (method, params = {}) => new Promise((resolve, reject) => { const id = ++seq; pending.set(id, { resolve, reject }); ws.send(JSON.stringify({ id, method, params })); });
const ev = async expression => {
  const r = await cdp("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
  if (r.exceptionDetails) throw Error(JSON.stringify(r.exceptionDetails));
  return r.result?.value;
};
const wait = async expr => { for (let i = 0; i < 150; i++) { if (await ev(expr)) return; await new Promise(r => setTimeout(r, 100)); } throw Error(`Timeout ${expr}`); };
const sel = id => `[data-testid="${id}"]`;
const clickSelector = async selector => {
  const p = await ev(`(() => { const e=document.querySelector(${JSON.stringify(selector)}); e.scrollIntoView({block:"center"}); const r=e.getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);
  await cdp("Input.dispatchMouseEvent", { type: "mousePressed", ...p, button: "left", clickCount: 1 });
  await cdp("Input.dispatchMouseEvent", { type: "mouseReleased", ...p, button: "left", clickCount: 1 });
};
const click = id => clickSelector(sel(id));
const input = async (id, value) => ev(`(() => {const e=document.querySelector(${JSON.stringify(sel(id))});Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,"value").set.call(e,${JSON.stringify(value)});e.dispatchEvent(new Event("input",{bubbles:true}));})()`);
const choose = async (id, text) => {
  await click(id);
  await wait(`Array.from(document.querySelectorAll('[role="option"]')).some(e=>e.textContent.includes(${JSON.stringify(text)}))`);
  await ev(`Array.from(document.querySelectorAll('[role="option"]')).find(e=>e.textContent.includes(${JSON.stringify(text)})).setAttribute("data-mat03-option","yes")`);
  await clickSelector('[data-mat03-option="yes"]');
};
const shot = async name => {
  await ev(`Object.assign(document.querySelector('[data-testid="mat02-fixture-disclosure"]').style,{position:"fixed",top:"0",left:"0",right:"0",zIndex:"9999"})`);
  const r = await cdp("Page.captureScreenshot", { format: "png", captureBeyondViewport: false });
  writeFileSync(`${out}/${name}-SYNTHETIC.png`, Buffer.from(r.data, "base64"));
};
await cdp("Page.enable");
await cdp("Emulation.setDeviceMetricsOverride", { width: 1600, height: 1200, deviceScaleFactor: 1, mobile: false });
await cdp("Page.navigate", { url: "http://127.0.0.1:4183/site/material-trips?scenario=mat03" });
await wait(`!!document.querySelector('${sel("select-trip-site")}')`);
await ev(`sessionStorage.removeItem("mat03-created")`);
await choose("select-trip-site", "MAT02 SYNTHETIC SITE");
await choose("select-trip-material", "WMM");
await input("input-trip-quantity", "800");
await input("input-trip-supplier", "SYNTHETIC TRANSPORTER");
await input("input-trip-vehicle", "SYNTHETIC-03");
await choose("select-trip-worktype", "Road");
await choose("select-trip-transport-type", "Agency");
await wait(`!!document.querySelector('${sel("trip-work-ctx-select-item")}')`);
await choose("trip-work-ctx-select-item", "SYNTHETIC WMM");
await shot("B-create-road");
await click("button-submit-trip");
await wait(`window.__mat03Writes?.some(w=>w.method==="POST")`);
const create = await ev(`window.__mat03Writes`);
await wait(`!!document.querySelector('${sel("row-trip-13022")}')`);
await ev(`document.querySelector('${sel("row-trip-13022")}').scrollIntoView({block:"center"})`);
await shot("BC-created-trip-table");
const tripTableText = await ev(`document.querySelector('${sel("row-trip-13022")}').textContent`);
await cdp("Page.navigate", { url: "http://127.0.0.1:4183/site/materials-received?scenario=mat03" });
await wait(`!!document.querySelector('${sel("row-material-trip-13022")}')`);
await shot("BC-received-table-road-conversion");
const receivedTableText = await ev(`document.querySelector('${sel("row-material-trip-13022")}').textContent`);
if (!receivedTableText.includes("ROAD") || !receivedTableText.includes("22.653 Cum")) throw Error("Created table missing Road or BOQ conversion");
await click("row-material-trip-13022");
await wait(`!!document.querySelector('${sel("btn-admin-edit")}')`);
await shot("BC-detail-road-conversion");
const detailText = await ev(`document.querySelector('[role="dialog"]').textContent`);
if (!detailText.includes("ROAD") || !detailText.includes("22.653 Cum")) throw Error("Created detail missing Road or BOQ conversion");
await click("btn-admin-edit");
await wait(`!!document.querySelector('${sel("select-edit-unloaded-at")}')`);
if (!(await ev(`document.querySelector('${sel("select-edit-unloaded-at")}').textContent.includes("Stretch")`))) throw Error("Existing stretch not shown");
await choose("select-edit-unloaded-at", "Temporary Yard");
await input("input-edit-yard-label", "SYNTHETIC SAVED YARD");
await shot("E-edit-yard");
await click("button-save-edit");
await wait(`window.__mat03Writes?.some(w=>w.method==="PATCH")`);
await wait(`!document.querySelector('${sel("button-save-edit")}')`);
await click("btn-admin-edit");
await wait(`document.querySelector('${sel("input-edit-yard-label")}')?.value==="SYNTHETIC SAVED YARD"`);
await shot("E-saved-yard-reopened");
await choose("select-edit-unloaded-at", "Work Stretch");
if (await ev(`!!document.querySelector('${sel("input-edit-yard-label")}')`)) throw Error("Yard label should hide");
await click("button-save-edit");
await wait(`window.__mat03Writes.length===2`);
const edits = await ev(`window.__mat03Writes`);
if (create[0].payload.workType !== "road" || create[0].returned.workType !== "road") throw Error("WorkType payload/return lost");
if (edits[0].returned.yardLabel !== "SYNTHETIC SAVED YARD" || edits[1].payload.yardLabel !== null) throw Error("Yard edit payload lost");
await cdp("Page.navigate", { url: "http://127.0.0.1:4183/site/materials-received?scenario=mat03&legacy=1" });
await wait(`!!document.querySelector('${sel("row-material-trip-13022")}')`);
await click("row-material-trip-13022");
await wait(`!!document.querySelector('${sel("btn-admin-edit")}')`);
await click("btn-admin-edit");
await wait(`!!document.querySelector('${sel("select-edit-unloaded-at")}')`);
const legacyUnloadingText = await ev(`document.querySelector('${sel("select-edit-unloaded-at")}').textContent`);
if (!legacyUnloadingText.includes("Select unloading point")) throw Error("Legacy unloading point should be blank, not defaulted");
await shot("E-legacy-unloading-blank");
await cdp("Page.navigate", { url: "http://127.0.0.1:4183/site/edit/3?scenario=mat03" });
await wait(`document.body.innerText.includes("No manually-added materials for today.") && !!document.querySelector('${sel("edit-materials-day-trip-13021")}')`);
await ev(`document.querySelector('${sel("button-add-material-top")}').scrollIntoView({block:"center"})`);
await shot("AC-dpr-trips-and-manual-empty");
const dprText = await ev(`document.body.innerText`);
const unlinked = await ev(`document.querySelector('${sel("edit-materials-day-trip-13023")}').textContent`);
const missingDensity = await ev(`document.querySelector('${sel("edit-materials-day-trip-13024")}').textContent`);
if (unlinked.includes("BOQ unit") || missingDensity.includes("BOQ unit")) throw Error("Fabricated fallback conversion");
writeFileSync(`${out}/payload-render-proof.json`, JSON.stringify({ synthetic: true, noLiveWrites: true, handcheck: { formula: "800 / 35.3147", result: 800 / 35.3147, displayed: "22.653 Cum" }, create, edits, rendered: { tripTableText, receivedTableText, detailText, legacyUnloadingText, dprManualEmpty: dprText.includes("No manually-added materials for today."), unlinked, missingDensity } }, null, 2));
console.log("MAT03 browser create/display/edit assertions passed");
ws.close();